{
  "name": "Turnos Rotativos - Shift Manager",
  "description": "A sophisticated rotating shift management application for workers to track schedules, visualize rotations, and get AI-powered insights into their work-life balance.",
  "requestFramePermissions": []
}

export enum ShiftType {
  MORNING = 'morning',
  AFTERNOON = 'afternoon',
  NIGHT = 'night',
  OFF = 'off'
}

export interface RotationWeek {
  id: string;
  shiftType: ShiftType;
}

export interface UserConfig {
  startDate: string; // ISO Date
  rotation: RotationWeek[];
}

export interface AppState {
  isRegistered: boolean;
  config: UserConfig;
}

import React from 'react';
import { ShiftType } from './types';

export const SHIFT_DETAILS = {
  [ShiftType.MORNING]: {
    label: 'Mañana',
    icon: 'wb_sunny',
    color: 'text-amber-500',
    bg: 'bg-amber-400/10',
    border: 'border-amber-400',
    time: '06:00 - 14:00',
    dot: 'bg-shift-morning'
  },
  [ShiftType.AFTERNOON]: {
    label: 'Tarde',
    icon: 'wb_twilight',
    color: 'text-orange-500',
    bg: 'bg-orange-500/10',
    border: 'border-orange-500',
    time: '14:00 - 22:00',
    dot: 'bg-shift-afternoon'
  },
  [ShiftType.NIGHT]: {
    label: 'Noche',
    icon: 'bedtime',
    color: 'text-indigo-500',
    bg: 'bg-indigo-500/10',
    border: 'border-indigo-500',
    time: '22:00 - 06:00',
    dot: 'bg-shift-night'
  },
  [ShiftType.OFF]: {
    label: 'Libre',
    icon: 'block',
    color: 'text-slate-400',
    bg: 'bg-slate-100 dark:bg-slate-800',
    border: 'border-gray-200 dark:border-gray-700',
    time: 'Descanso',
    dot: 'bg-transparent'
  }
};

export const WEEK_DAYS = ['L', 'M', 'X', 'J', 'V', 'S', 'D'];

import { GoogleGenAI } from "@google/genai";
import { UserConfig, ShiftType } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const getShiftInsights = async (config: UserConfig) => {
  const rotationStr = config.rotation.map((w, i) => `Semana ${i + 1}: ${w.shiftType}`).join(", ");
  const prompt = `
    Basado en el siguiente patrón de turnos rotativos: ${rotationStr}.
    El ciclo comienza el ${config.startDate}.
    Proporciona 3 consejos breves y amigables sobre salud y organización para este trabajador.
    Enfócate en el sueño, alimentación o vida social.
    Responde en español, tono motivador y corto.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text;
  } catch (error) {
    console.error("Error fetching insights:", error);
    return "Mantente hidratado y descansa bien entre turnos.";
  }
};

import React from 'react';
import { Link, useLocation } from 'react-router-dom';

const BottomNav: React.FC = () => {
  const location = useLocation();
  const path = location.pathname;

  const NavItem = ({ to, icon, label, active }: { to: string; icon: string; label: string; active: boolean }) => (
    <Link to={to} className={`flex flex-1 flex-col items-center justify-center gap-1 h-full transition-colors group ${active ? 'text-primary relative' : 'text-slate-400 hover:text-primary'}`}>
      {active && <div className="absolute -top-[1px] w-12 h-[2px] bg-primary rounded-b-full shadow-[0_2px_8px_rgba(19,127,236,0.5)]"></div>}
      <span className={`material-symbols-outlined ${active ? 'fill' : 'group-hover:-translate-y-0.5 transition-transform duration-300'}`}>{icon}</span>
      <span className={`text-[10px] font-medium tracking-wide ${active ? 'font-bold' : ''}`}>{label}</span>
    </Link>
  );

  return (
    <nav className="fixed bottom-0 z-50 w-full bg-white/90 dark:bg-[#192633]/95 backdrop-blur-xl border-t border-gray-200 dark:border-gray-800 pb-safe">
      <div className="flex justify-around items-center px-2 h-16">
        <NavItem to="/dashboard" icon="dashboard" label="Inicio" active={path === '/dashboard'} />
        <NavItem to="/month" icon="calendar_month" label="Mensual" active={path === '/month'} />
        <NavItem to="/week" icon="view_week" label="Semanal" active={path === '/week'} />
        <NavItem to="/config" icon="settings" label="Ajustes" active={path === '/config'} />
      </div>
    </nav>
  );
};

export default BottomNav;

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AppState, UserConfig, ShiftType } from './types';
import RegistrationScreen from './screens/RegistrationScreen';
import ConfigScreen from './screens/ConfigScreen';
import DashboardScreen from './screens/DashboardScreen';
import MonthlyScreen from './screens/MonthlyScreen';
import WeeklyScreen from './screens/WeeklyScreen';

const DEFAULT_CONFIG: UserConfig = {
  startDate: new Date().toISOString().split('T')[0],
  rotation: [
    { id: '1', shiftType: ShiftType.MORNING },
    { id: '2', shiftType: ShiftType.AFTERNOON },
    { id: '3', shiftType: ShiftType.NIGHT },
  ]
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('turnos_app_state');
    return saved ? JSON.parse(saved) : {
      isRegistered: false,
      config: DEFAULT_CONFIG
    };
  });

  useEffect(() => {
    localStorage.setItem('turnos_app_state', JSON.stringify(appState));
  }, [appState]);

  const handleRegister = () => {
    setAppState(prev => ({ ...prev, isRegistered: true }));
  };

  const updateConfig = (newConfig: UserConfig) => {
    setAppState(prev => ({ ...prev, config: newConfig }));
  };

  return (
    <HashRouter>
      <Routes>
        <Route path="/" element={!appState.isRegistered ? <RegistrationScreen onRegister={handleRegister} /> : <Navigate to="/dashboard" />} />
        <Route path="/config" element={<ConfigScreen config={appState.config} onUpdate={updateConfig} />} />
        <Route path="/dashboard" element={<DashboardScreen config={appState.config} />} />
        <Route path="/month" element={<MonthlyScreen config={appState.config} />} />
        <Route path="/week" element={<WeeklyScreen config={appState.config} />} />
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </HashRouter>
  );
};

export default App;

import React from 'react';
import { useNavigate } from 'react-router-dom';
import { UserConfig, ShiftType, RotationWeek } from '../types';
import { SHIFT_DETAILS } from '../constants';
import BottomNav from '../components/BottomNav';

interface ConfigScreenProps {
  config: UserConfig;
  onUpdate: (config: UserConfig) => void;
}

const ConfigScreen: React.FC<ConfigScreenProps> = ({ config, onUpdate }) => {
  const navigate = useNavigate();

  const addWeek = () => {
    const newWeek: RotationWeek = {
      id: Math.random().toString(36).substr(2, 9),
      shiftType: ShiftType.MORNING
    };
    onUpdate({ ...config, rotation: [...config.rotation, newWeek] });
  };

  const removeWeek = (id: string) => {
    onUpdate({ ...config, rotation: config.rotation.filter(w => w.id !== id) });
  };

  const updateWeekShift = (id: string, shift: ShiftType) => {
    onUpdate({
      ...config,
      rotation: config.rotation.map(w => w.id === id ? { ...w, shiftType: shift } : w)
    });
  };

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate({ ...config, startDate: e.target.value });
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden pb-24">
      <div className="flex items-center bg-background-light dark:bg-background-dark p-4 pb-2 justify-between sticky top-0 z-50 border-b border-gray-200 dark:border-gray-800">
        <button onClick={() => navigate(-1)} className="text-[#111418] dark:text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
          <span className="material-symbols-outlined text-[24px]">arrow_back</span>
        </button>
        <h2 className="text-[#111418] dark:text-white text-lg font-bold leading-tight tracking-[-0.015em] flex-1 text-center pr-12">Configuración</h2>
      </div>

      <div className="flex flex-col px-4 pt-6 pb-2">
        <h1 className="text-[#111418] dark:text-white tracking-light text-[28px] font-bold leading-tight text-left">Define tu Rotación</h1>
        <p className="text-[#637588] dark:text-[#9eaec0] text-base font-normal leading-normal pt-2">
          Elige cuándo inicia tu ciclo y el orden de los turnos para generar tu calendario.
        </p>
      </div>

      <div className="flex flex-col mt-4">
        <h3 className="text-[#111418] dark:text-white text-lg font-bold leading-tight tracking-[-0.015em] px-4 pb-3">Fecha de Inicio</h3>
        <div className="px-4">
          <div className="bg-white dark:bg-surface-dark rounded-xl p-4 flex items-center justify-between border border-gray-200 dark:border-gray-800 shadow-sm">
            <div className="flex items-center gap-4">
              <div className="bg-primary/10 text-primary flex items-center justify-center size-10 rounded-full">
                <span className="material-symbols-outlined text-[22px]">calendar_today</span>
              </div>
              <input 
                type="date" 
                value={config.startDate}
                onChange={handleDateChange}
                className="bg-transparent border-none focus:ring-0 text-[#111418] dark:text-white text-lg font-semibold cursor-pointer"
              />
            </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col mt-8">
        <div className="flex items-center justify-between px-4 pb-3">
          <h3 className="text-[#111418] dark:text-white text-lg font-bold leading-tight tracking-[-0.015em]">Orden de Turnos</h3>
          <span className="text-xs font-medium text-primary bg-primary/10 px-2 py-1 rounded-full">{config.rotation.length} Semanas</span>
        </div>
        <div className="flex flex-col gap-4 px-4">
          {config.rotation.map((week, index) => (
            <div key={week.id} className="relative flex flex-col gap-3 bg-white dark:bg-surface-dark rounded-xl p-4 border border-gray-200 dark:border-gray-800 shadow-sm">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <span className="material-symbols-outlined text-[#637588] dark:text-[#506070]">drag_indicator</span>
                  <span className="text-[#111418] dark:text-white text-base font-bold">Semana {index + 1}</span>
                </div>
                <button 
                  onClick={() => removeWeek(week.id)}
                  disabled={config.rotation.length <= 1}
                  className="text-[#637588] dark:text-[#9eaec0] hover:text-red-500 transition-colors disabled:opacity-30"
                >
                  <span className="material-symbols-outlined text-[20px]">delete</span>
                </button>
              </div>
              <div className="flex gap-2 overflow-x-auto no-scrollbar pb-1">
                {(Object.keys(SHIFT_DETAILS) as ShiftType[]).map((st) => {
                  const details = SHIFT_DETAILS[st];
                  const isActive = week.shiftType === st;
                  return (
                    <button 
                      key={st}
                      onClick={() => updateWeekShift(week.id, st)}
                      className={`flex-1 min-w-[80px] flex flex-col items-center justify-center gap-1 p-2 rounded-lg transition-all ${isActive ? `border-2 ${details.border} ${details.bg}` : 'border border-gray-200 dark:border-gray-700 bg-transparent opacity-60'}`}
                    >
                      <span className={`material-symbols-outlined text-[20px] ${details.color} ${isActive ? 'fill' : ''}`}>{details.icon}</span>
                      <span className={`text-xs font-semibold ${isActive ? details.color : 'text-[#637588] dark:text-[#9eaec0] font-medium'}`}>{details.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
          <button onClick={addWeek} className="flex items-center justify-center gap-2 p-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-gray-700 text-[#637588] dark:text-[#9eaec0] hover:border-primary hover:text-primary transition-all group bg-transparent">
            <span className="material-symbols-outlined group-hover:scale-110 transition-transform">add_circle</span>
            <span className="font-semibold">Agregar semana al ciclo</span>
          </button>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 w-full bg-white/80 dark:bg-background-dark/95 backdrop-blur-md p-4 border-t border-gray-200 dark:border-gray-800 z-40">
        <button onClick={() => navigate('/dashboard')} className="w-full bg-primary hover:bg-blue-600 text-white font-bold text-lg h-12 rounded-xl shadow-lg shadow-primary/25 flex items-center justify-center gap-2 transition-all active:scale-[0.98]">
          <span className="material-symbols-outlined">auto_awesome</span>
          Generar Calendario
        </button>
      </div>
      <BottomNav />
    </div>
  );
};

export default ConfigScreen;

import React, { useState, useEffect, useCallback } from 'react';
import { UserConfig, ShiftType } from '../types';
