}

const DashboardScreen: React.FC<DashboardScreenProps> = ({ config }) => {
  const [insights, setInsights] = useState<string>("Cargando recomendaciones personalizadas...");

  const getShiftForDate = useCallback((date: Date) => {
    const start = new Date(config.startDate);
    const diff = Math.floor((date.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
    if (diff < 0) return ShiftType.OFF;

    const cycleDays = config.rotation.length * 7;
    const currentDayInCycle = diff % cycleDays;
    const weekIndex = Math.floor(currentDayInCycle / 7);
    return config.rotation[weekIndex].shiftType;
  }, [config]);

  useEffect(() => {
