export default DashboardScreen;

import React, { useState, useMemo } from 'react';
import { UserConfig, ShiftType } from '../types';
import { SHIFT_DETAILS, WEEK_DAYS } from '../constants';
import BottomNav from '../components/BottomNav';

interface MonthlyScreenProps {
  config: UserConfig;
}

const MonthlyScreen: React.FC<MonthlyScreenProps> = ({ config }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const getShiftForDate = (date: Date) => {
    const start = new Date(config.startDate);
    const startMidnight = new Date(start.getFullYear(), start.getMonth(), start.getDate());
    const dateMidnight = new Date(date.getFullYear(), date.getMonth(), date.getDate());

    const diff = Math.floor((dateMidnight.getTime() - startMidnight.getTime()) / (1000 * 60 * 60 * 24));
    if (diff < 0) return ShiftType.OFF;

    const cycleDays = config.rotation.length * 7;
    const currentDayInCycle = diff % cycleDays;
    const weekIndex = Math.floor(currentDayInCycle / 7);
    return config.rotation[weekIndex].shiftType;
  };

  const calendarData = useMemo(() => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const firstDay = new Date(year, month, 1).getDay(); // 0 (Sun) to 6 (Sat)
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    // Normalize firstDay to 0 = Monday
    const adjustedFirstDay = firstDay === 0 ? 6 : firstDay - 1;

    const days = [];
    for (let i = 0; i < adjustedFirstDay; i++) {
      days.push(null);
    }
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(new Date(year, month, i));
    }
    return days;
  }, [currentMonth]);

  const shiftCounts = useMemo(() => {
    const counts = { [ShiftType.MORNING]: 0, [ShiftType.AFTERNOON]: 0, [ShiftType.NIGHT]: 0, [ShiftType.OFF]: 0 };
    calendarData.forEach(d => {
      if (d) counts[getShiftForDate(d)]++;
    });
    return counts;
  }, [calendarData, config]);

  const changeMonth = (offset: number) => {
    setCurrentMonth(prev => new Date(prev.getFullYear(), prev.getMonth() + offset, 1));
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden pb-24">
      <header className="sticky top-0 z-50 flex items-center justify-between bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md px-4 py-3 border-b border-gray-200 dark:border-gray-800">
        <button onClick={() => changeMonth(-1)} className="flex size-10 items-center justify-center rounded-full text-slate-600 dark:text-white hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
          <span className="material-symbols-outlined">chevron_left</span>
        </button>
        <h1 className="text-lg font-bold leading-tight tracking-tight uppercase">
          {currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
        </h1>
        <button onClick={() => changeMonth(1)} className="flex size-10 items-center justify-center rounded-full text-slate-600 dark:text-white hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
          <span className="material-symbols-outlined">chevron_right</span>
        </button>
      </header>

      <section className="px-4 pt-4 pb-2">
        <div className="grid grid-cols-3 gap-3">
          <div className="flex flex-col items-center justify-center p-3 rounded-xl bg-white dark:bg-card-dark border border-gray-100 dark:border-gray-800 shadow-sm">
            <span className="text-2xl font-bold text-shift-morning tracking-tight">{shiftCounts[ShiftType.MORNING]}</span>
            <span className="text-[11px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Mañanas</span>
          </div>
          <div className="flex flex-col items-center justify-center p-3 rounded-xl bg-white dark:bg-card-dark border border-gray-100 dark:border-gray-800 shadow-sm">
