import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { UserConfig, ShiftType } from '../types';
import { SHIFT_DETAILS, WEEK_DAYS } from '../constants';
import BottomNav from '../components/BottomNav';

interface MonthlyScreenProps {
  config: UserConfig;
}

const MonthlyScreen: React.FC<MonthlyScreenProps> = ({ config }) => {
  const navigate = useNavigate();
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date>(new Date());

  const getShiftForDate = (date: Date) => {
    const start = new Date(config.startDate);
    const startMidnight = new Date(start.getFullYear(), start.getMonth(), start.getDate());
    const dateMidnight = new Date(date.getFullYear(), date.getMonth(), date.getDate());

    const diff = Math.floor((dateMidnight.getTime() - startMidnight.getTime()) / (1000 * 60 * 60 * 24));
    if (diff < 0) return ShiftType.OFF;

    const cycleDays = config.rotation.length * 7;
    const currentDayInCycle = diff % cycleDays;
    const weekIndex = Math.floor(currentDayInCycle / 7);
    return config.rotation[weekIndex].shiftType;
  };

  const calendarData = useMemo(() => {
    const year = currentMonth.getFullYear();
    const month = currentMonth.getMonth();
    const firstDay = new Date(year, month, 1).getDay(); // 0 (Sun) to 6 (Sat)
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    // Normalize firstDay to 0 = Monday
    const adjustedFirstDay = firstDay === 0 ? 6 : firstDay - 1;

    const days = [];
    for (let i = 0; i < adjustedFirstDay; i++) {
      days.push(null);
    }
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(new Date(year, month, i));
    }
    return days;
  }, [currentMonth]);

  const shiftCounts = useMemo(() => {
    const counts = { [ShiftType.MORNING]: 0, [ShiftType.AFTERNOON]: 0, [ShiftType.NIGHT]: 0, [ShiftType.OFF]: 0 };
    calendarData.forEach(d => {
      if (d) counts[getShiftForDate(d)]++;
    });
    return counts;
  }, [calendarData, config]);

  const changeMonth = (offset: number) => {
    setCurrentMonth(prev => new Date(prev.getFullYear(), prev.getMonth() + offset, 1));
  };

  const currentShiftType = getShiftForDate(selectedDate);
  const currentDetails = SHIFT_DETAILS[currentShiftType];

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden pb-24">
      <header className="sticky top-0 z-50 flex items-center justify-between bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-md px-4 py-3 border-b border-gray-200 dark:border-gray-800">
        <button onClick={() => changeMonth(-1)} className="flex size-10 items-center justify-center rounded-full text-slate-600 dark:text-white hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
          <span className="material-symbols-outlined">chevron_left</span>
        </button>
        <h1 className="text-lg font-bold leading-tight tracking-tight uppercase">
          {currentMonth.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}
        </h1>
        <button onClick={() => changeMonth(1)} className="flex size-10 items-center justify-center rounded-full text-slate-600 dark:text-white hover:bg-black/5 dark:hover:bg-white/10 transition-colors">
          <span className="material-symbols-outlined">chevron_right</span>
        </button>
      </header>

      <section className="px-4 pt-4 pb-2">
        <div className="grid grid-cols-3 gap-3">
          <div className="flex flex-col items-center justify-center p-3 rounded-xl bg-white dark:bg-card-dark border border-gray-100 dark:border-gray-800 shadow-sm">
            <span className="text-2xl font-bold text-shift-morning tracking-tight">{shiftCounts[ShiftType.MORNING]}</span>
            <span className="text-[11px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Mañanas</span>
          </div>
          <div className="flex flex-col items-center justify-center p-3 rounded-xl bg-white dark:bg-card-dark border border-gray-100 dark:border-gray-800 shadow-sm">
            <span className="text-2xl font-bold text-shift-afternoon tracking-tight">{shiftCounts[ShiftType.AFTERNOON]}</span>
            <span className="text-[11px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Tardes</span>
          </div>
          <div className="flex flex-col items-center justify-center p-3 rounded-xl bg-white dark:bg-card-dark border border-gray-100 dark:border-gray-800 shadow-sm">
            <span className="text-2xl font-bold text-shift-night tracking-tight">{shiftCounts[ShiftType.NIGHT]}</span>
            <span className="text-[11px] font-semibold text-gray-500 dark:text-gray-400 uppercase tracking-wide">Noches</span>
          </div>
        </div>
      </section>

      <section className="flex flex-col p-4 pt-2">
        <div className="grid grid-cols-7 mb-2 border-b border-gray-100 dark:border-gray-800 pb-2">
          {WEEK_DAYS.map((d, i) => (
            <div key={i} className={`text-center text-[11px] font-bold ${i >= 5 ? 'text-rose-500/80 dark:text-rose-400/80' : 'text-gray-400 dark:text-gray-500'}`}>{d}</div>
          ))}
        </div>
        <div className="grid grid-cols-7 gap-y-4 gap-x-1">
          {calendarData.map((d, i) => {
            if (!d) return <div key={i} className="h-14"></div>;
            const shiftType = getShiftForDate(d);
            const isToday = d.toDateString() === new Date().toDateString();
            const isSelected = d.toDateString() === selectedDate.toDateString();
            const details = SHIFT_DETAILS[shiftType];

            return (
              <button 
                key={i} 
                onClick={() => setSelectedDate(d)}
                className="flex flex-col items-center justify-start h-14 w-full gap-1 group relative outline-none"
              >
                <span className={`flex size-8 items-center justify-center rounded-full text-sm font-medium transition-all ${isSelected ? 'ring-2 ring-primary ring-offset-2 dark:ring-offset-background-dark' : ''} ${isToday ? 'bg-primary text-white shadow-glow' : 'text-slate-700 dark:text-slate-300 hover:bg-black/5 dark:hover:bg-white/5'}`}>
                  {d.getDate()}
                </span>
                {shiftType !== ShiftType.OFF && (
                  <div className={`h-1.5 w-5 rounded-full ${details.dot} shadow-sm`}></div>
                )}
              </button>
            );
          })}
        </div>
      </section>

      <section className="px-4 mt-2">
        <div className="flex flex-col gap-4 rounded-2xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-card-dark p-5 shadow-lg dark:shadow-none">
          <div className="flex items-start justify-between">
            <div className="flex flex-col gap-1">
              <p className="text-lg font-bold text-slate-900 dark:text-white">
                {selectedDate.toLocaleDateString('es-ES', { day: 'numeric', month: 'short' })}
                {selectedDate.toDateString() === new Date().toDateString() ? ' (Hoy)' : ''}
              </p>
              <div className="flex items-center gap-2">
                <div className={`flex size-2.5 rounded-full ${currentDetails.dot} shadow-glow`}></div>
                <p className="text-slate-500 dark:text-gray-300 text-sm font-medium">Turno {currentDetails.label}</p>
              </div>
            </div>
            <button 
              onClick={() => navigate('/config')}
              className="group flex items-center justify-center size-9 rounded-full bg-gray-100 dark:bg-gray-800 text-primary hover:bg-primary hover:text-white transition-all"
            >
              <span className="material-symbols-outlined text-[20px]">edit</span>
            </button>
          </div>
          <div className="w-full h-px bg-gray-100 dark:bg-gray-700/50"></div>
          <div className="flex items-center gap-3">
            <div className="flex size-8 items-center justify-center rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 dark:text-slate-400">
              <span className="material-symbols-outlined text-[18px]">schedule</span>
            </div>
            <div>
              <p className="text-xs text-slate-400 font-medium uppercase tracking-wide">Horario</p>
              <p className="text-sm font-semibold text-slate-700 dark:text-slate-200">{currentDetails.time}</p>
            </div>
          </div>
        </div>
      </section>

      <BottomNav />
    </div>
  );
};

export default MonthlyScreen;

import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { UserConfig, ShiftType } from '../types';
import { SHIFT_DETAILS } from '../constants';
import BottomNav from '../components/BottomNav';

interface WeeklyScreenProps {
  config: UserConfig;
}

const WeeklyScreen: React.FC<WeeklyScreenProps> = ({ config }) => {
  const navigate = useNavigate();
  const [currentWeekOffset, setCurrentWeekOffset] = useState(0);

  const getShiftForDate = (date: Date) => {
    const start = new Date(config.startDate);
    const startMidnight = new Date(start.getFullYear(), start.getMonth(), start.getDate());
    const dateMidnight = new Date(date.getFullYear(), date.getMonth(), date.getDate());

    const diff = Math.floor((dateMidnight.getTime() - startMidnight.getTime()) / (1000 * 60 * 60 * 24));
    if (diff < 0) return ShiftType.OFF;

    const cycleDays = config.rotation.length * 7;
    const currentDayInCycle = diff % cycleDays;
    const weekIndex = Math.floor(currentDayInCycle / 7);
    return config.rotation[weekIndex].shiftType;
  };

  const weekDays = useMemo(() => {
    const now = new Date();
    const day = now.getDay();
    const diffToMonday = now.getDate() - day + (day === 0 ? -6 : 1);
    const baseMonday = new Date(now.setDate(diffToMonday));
    baseMonday.setHours(0, 0, 0, 0);

    const targetMonday = new Date(baseMonday);
    targetMonday.setDate(baseMonday.getDate() + (currentWeekOffset * 7));

    const days = [];
    for (let i = 0; i < 7; i++) {
      const nextDay = new Date(targetMonday);
      nextDay.setDate(targetMonday.getDate() + i);
      days.push(nextDay);
    }
    return days;
  }, [currentWeekOffset]);

  return (
    <div className="relative flex min-h-screen w-full flex-col max-w-md mx-auto bg-background-light dark:bg-background-dark shadow-2xl">
      <header className="sticky top-0 z-20 flex items-center justify-between bg-surface-light dark:bg-[#111a22]/95 backdrop-blur-md px-4 py-4 border-b border-gray-200 dark:border-[#233648]">
        <button 
          onClick={() => setCurrentWeekOffset(prev => prev - 1)}
          className="flex items-center justify-center p-2 rounded-full hover:bg-gray-100 dark:hover:bg-[#233648] transition-colors text-slate-600 dark:text-slate-200"
        >
          <span className="material-symbols-outlined text-2xl">chevron_left</span>
        </button>
        <div className="flex flex-col items-center">
          <h2 className="text-base font-bold leading-tight tracking-tight">
            {currentWeekOffset === 0 ? 'Esta Semana' : currentWeekOffset === 1 ? 'Próxima Semana' : currentWeekOffset === -1 ? 'Semana Pasada' : `Semana ${currentWeekOffset > 0 ? '+' : ''}${currentWeekOffset}`}
          </h2>
          <span className="text-xs font-medium text-slate-500 dark:text-[#92adc9]">
            {weekDays[0].toLocaleDateString('es-ES', { day: 'numeric', month: 'short' })} - {weekDays[6].toLocaleDateString('es-ES', { day: 'numeric', month: 'short' })}
          </span>
        </div>
        <button 
          onClick={() => setCurrentWeekOffset(prev => prev + 1)}
          className="flex items-center justify-center p-2 rounded-full hover:bg-gray-100 dark:hover:bg-[#233648] transition-colors text-slate-600 dark:text-slate-200"
        >
          <span className="material-symbols-outlined text-2xl">chevron_right</span>
        </button>
      </header>

      <main className="flex-1 flex flex-col gap-4 p-4 pb-24 overflow-y-auto">
        {weekDays.map((day, idx) => {
          const shiftType = getShiftForDate(day);
          const details = SHIFT_DETAILS[shiftType];
          const isToday = day.toDateString() === new Date().toDateString();

          return (
            <details 
              key={idx} 
              className={`group rounded-xl bg-surface-light dark:bg-surface-dark shadow-sm border ${isToday ? 'border-primary ring-1 ring-primary/20' : 'border-gray-200 dark:border-[#233648]'} overflow-hidden transition-all duration-300`}
              open={isToday}
            >
              <summary className={`flex cursor-pointer items-center justify-between p-4 bg-transparent hover:bg-gray-50 dark:hover:bg-[#233648]/50 transition-colors select-none ${isToday ? 'bg-primary/5' : ''}`}>
                <div className="flex items-center gap-4">
                  <div className="flex flex-col items-center justify-center w-10">
                    <span className={`text-xs font-semibold uppercase ${isToday ? 'text-primary' : 'text-slate-500 dark:text-[#92adc9]'}`}>
                      {day.toLocaleDateString('es-ES', { weekday: 'short' })}
                    </span>
                    <span className={`text-lg font-bold ${isToday ? 'text-primary' : 'text-slate-800 dark:text-white'}`}>
                      {day.getDate()}
                    </span>
                  </div>
                  <div className="h-8 w-[2px] bg-gray-200 dark:bg-[#233648] rounded-full"></div>
                  <div className="flex flex-col">
                    <div className="flex items-center gap-2">
                      <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wide ${details.bg} ${details.color} border ${details.border}/20`}>
                        {details.label}
