import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AppState, UserConfig, ShiftType, UserInfo } from './types';
import RegistrationScreen from './screens/RegistrationScreen';
import ConfigScreen from './screens/ConfigScreen';
import DashboardScreen from './screens/DashboardScreen';
import MonthlyScreen from './screens/MonthlyScreen';
import WeeklyScreen from './screens/WeeklyScreen';
import ProfileScreen from './screens/ProfileScreen';

const DEFAULT_CONFIG: UserConfig = {
  startDate: new Date().toISOString().split('T')[0],
  rotation: [
    { id: '1', shiftType: ShiftType.MORNING },
    { id: '2', shiftType: ShiftType.AFTERNOON },
    { id: '3', shiftType: ShiftType.NIGHT },
  ]
};

const DEFAULT_USER: UserInfo = {
  name: 'Usuario',
  email: 'ejemplo@correo.com'
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('turnos_app_state');
    if (saved) {
      const parsed = JSON.parse(saved);
      // Migration for old states without user info
      if (!parsed.user) parsed.user = DEFAULT_USER;
      return parsed;
    }
    return {
      isRegistered: false,
      config: DEFAULT_CONFIG,
      user: DEFAULT_USER
    };
  });

  useEffect(() => {
    localStorage.setItem('turnos_app_state', JSON.stringify(appState));
  }, [appState]);

  const handleRegister = (userInfo: UserInfo) => {
    setAppState(prev => ({ 
      ...prev, 
      isRegistered: true,
      user: userInfo 
    }));
  };

  const updateConfig = (newConfig: UserConfig) => {
    setAppState(prev => ({ ...prev, config: newConfig }));
  };

  const updateUserInfo = (userInfo: UserInfo) => {
    setAppState(prev => ({ ...prev, user: userInfo }));
  };

  const handleLogout = () => {
    // Before wiping state, keep user info for "login" simulation if desired
    // But for this request, we clear completely and redirect
    setAppState(prev => ({
      ...prev,
      isRegistered: false
    }));
    // We clear the item so the app starts fresh next reload
    localStorage.removeItem('turnos_app_state');
  };

  return (
    <HashRouter>
      <Routes>
        {/* Public Route: Registration/Login */}
        <Route 
          path="/" 
          element={!appState.isRegistered ? <RegistrationScreen onRegister={handleRegister} /> : <Navigate to="/dashboard" replace />} 
        />

        {/* Protected Routes */}
        {appState.isRegistered ? (
          <>
            <Route path="/config" element={<ConfigScreen config={appState.config} onUpdate={updateConfig} />} />
            <Route path="/dashboard" element={<DashboardScreen config={appState.config} user={appState.user} />} />
            <Route path="/month" element={<MonthlyScreen config={appState.config} />} />
            <Route path="/week" element={<WeeklyScreen config={appState.config} />} />
            <Route path="/profile" element={<ProfileScreen user={appState.user} onUpdate={updateUserInfo} onLogout={handleLogout} />} />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </>
        ) : (
          <Route path="*" element={<Navigate to="/" replace />} />
        )}
      </Routes>
    </HashRouter>
  );
};

export default App;

