export interface RotationWeek {
  id: string;
  shiftType: ShiftType;
}

export interface UserConfig {
  startDate: string; // ISO Date
  rotation: RotationWeek[];
}

export interface UserInfo {
  name: string;
  email: string;
  avatarUrl?: string;
}

export interface AppState {
  isRegistered: boolean;
  config: UserConfig;
  user: UserInfo;
}

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AppState, UserConfig, ShiftType, UserInfo } from './types';
import RegistrationScreen from './screens/RegistrationScreen';
import ConfigScreen from './screens/ConfigScreen';
import DashboardScreen from './screens/DashboardScreen';
import MonthlyScreen from './screens/MonthlyScreen';
import WeeklyScreen from './screens/WeeklyScreen';
import ProfileScreen from './screens/ProfileScreen';

const DEFAULT_AVATAR = 'https://ui-avatars.com/api/?name=User&background=137fec&color=fff';

const DEFAULT_CONFIG: UserConfig = {
  startDate: new Date().toISOString().split('T')[0],
  rotation: [
    { id: '1', shiftType: ShiftType.MORNING },
    { id: '2', shiftType: ShiftType.AFTERNOON },
    { id: '3', shiftType: ShiftType.NIGHT },
  ]
};

const DEFAULT_USER: UserInfo = {
  name: 'Usuario',
  email: 'ejemplo@correo.com',
  avatarUrl: DEFAULT_AVATAR
};

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(() => {
    const saved = localStorage.getItem('turnos_app_state');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (!parsed.user) parsed.user = DEFAULT_USER;
      if (!parsed.user.avatarUrl) parsed.user.avatarUrl = DEFAULT_AVATAR;
      return parsed;
    }
    return {
      isRegistered: false,
      config: DEFAULT_CONFIG,
      user: DEFAULT_USER
    };
  });

  useEffect(() => {
    if (appState.isRegistered) {
      localStorage.setItem('turnos_app_state', JSON.stringify(appState));
    }
  }, [appState]);

  const handleRegister = (userInfo: UserInfo) => {
    setAppState(prev => ({ 
      ...prev, 
      isRegistered: true,
      user: {
        ...userInfo,
        avatarUrl: userInfo.avatarUrl || DEFAULT_AVATAR
      }
    }));
  };

  const updateConfig = (newConfig: UserConfig) => {
    setAppState(prev => ({ ...prev, config: newConfig }));
  };

  const updateUserInfo = (userInfo: UserInfo) => {
    setAppState(prev => ({ ...prev, user: userInfo }));
  };

  const handleLogout = () => {
    // Limpieza agresiva del estado y almacenamiento
    localStorage.removeItem('turnos_app_state');
    setAppState({
      isRegistered: false,
      config: DEFAULT_CONFIG,
      user: DEFAULT_USER
    });
  };

  return (
    <HashRouter>
      <Routes>
        <Route 
          path="/" 
          element={!appState.isRegistered ? <RegistrationScreen onRegister={handleRegister} /> : <Navigate to="/dashboard" replace />} 
        />

        {appState.isRegistered ? (
          <>
            <Route path="/config" element={<ConfigScreen config={appState.config} onUpdate={updateConfig} />} />
            <Route path="/dashboard" element={<DashboardScreen config={appState.config} user={appState.user} />} />
            <Route path="/month" element={<MonthlyScreen config={appState.config} />} />
            <Route path="/week" element={<WeeklyScreen config={appState.config} />} />
            <Route path="/profile" element={<ProfileScreen user={appState.user} onUpdate={updateUserInfo} onLogout={handleLogout} />} />
            <Route path="*" element={<Navigate to="/dashboard" replace />} />
          </>
        ) : (
          <Route path="*" element={<Navigate to="/" replace />} />
        )}
      </Routes>
    </HashRouter>
  );
};

export default App;

import React, { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { UserConfig, ShiftType, UserInfo } from '../types';
import { SHIFT_DETAILS } from '../constants';
import BottomNav from '../components/BottomNav';

interface DashboardScreenProps {
  config: UserConfig;
  user: UserInfo;
}

const DashboardScreen: React.FC<DashboardScreenProps> = ({ config, user }) => {
  const navigate = useNavigate();
  const getShiftForDate = useCallback((date: Date) => {
    const start = new Date(config.startDate);
    const diff = Math.floor((date.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
    if (diff < 0) return ShiftType.OFF;

    const cycleDays = config.rotation.length * 7;
    const currentDayInCycle = diff % cycleDays;
    const weekIndex = Math.floor(currentDayInCycle / 7);
    return config.rotation[weekIndex].shiftType;
  }, [config]);

  const now = new Date();
  const todayShiftType = getShiftForDate(now);
  const tomorrowShiftType = getShiftForDate(new Date(now.getTime() + 86400000));

  const todayDetails = SHIFT_DETAILS[todayShiftType];
  const tomorrowDetails = SHIFT_DETAILS[tomorrowShiftType];

  return (
    <div className="relative flex flex-col min-h-screen w-full overflow-x-hidden pb-[88px]">
      <header className="flex items-center justify-between px-6 pt-8 pb-4 sticky top-0 z-40 bg-background-light/95 dark:bg-background-dark/95 backdrop-blur-sm">
        <div className="flex flex-col">
          <p className="text-sm font-medium text-slate-500 dark:text-slate-400">
            {now.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'short' })}
          </p>
          <h1 className="text-2xl font-bold tracking-tight">Hola, {user.name}</h1>
        </div>
        <button 
          onClick={() => navigate('/profile')}
          className="relative group transition-transform active:scale-90"
        >
          <div className="bg-center bg-no-repeat bg-cover rounded-full size-12 ring-2 ring-primary/20" style={{backgroundImage: `url("${user.avatarUrl}")`}}></div>
          <div className="absolute -top-1 -right-1 size-3 bg-green-500 rounded-full border-2 border-background-light dark:border-background-dark"></div>
        </button>
      </header>

      <section className="px-4 mt-2 mb-6">
        <div className="flex items-center justify-between mb-3 px-2">
          <h2 className="text-lg font-bold tracking-tight">Turno Actual</h2>
          <span className="text-xs font-semibold px-2 py-1 rounded bg-green-500/10 text-green-600 dark:text-green-400 border border-green-500/20">En curso</span>
        </div>
        <div className="relative overflow-hidden rounded-2xl shadow-lg group">
          <div className="absolute inset-0 bg-cover bg-center transition-transform duration-700 group-hover:scale-105" style={{backgroundImage: 'url("https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=800&q=80")'}}></div>
          <div className="absolute inset-0 bg-gradient-to-t from-black via-black/60 to-black/30"></div>
          <div className="relative z-10 p-6 flex flex-col h-[200px] justify-between">
            <div className="flex justify-between items-start">
              <div className="flex flex-col">
                <div className="flex items-center gap-2 mb-1">
                  <span className={`material-symbols-outlined ${todayDetails.color} filled text-[20px]`}>{todayDetails.icon}</span>
                  <span className={`${todayDetails.color} font-bold uppercase tracking-wider text-xs`}>{todayDetails.label}</span>
                </div>
                <h3 className="text-white text-3xl font-bold tracking-tight">{todayDetails.time}</h3>
              </div>
              <button 
                onClick={() => navigate('/month')}
                className="bg-white/10 hover:bg-white/20 p-2 rounded-full backdrop-blur-md transition-colors text-white"
              >
                <span className="material-symbols-outlined">more_horiz</span>
              </button>
            </div>
            <div className="w-full">
              <div className="flex justify-between items-end mb-2">
                <span className="text-slate-200 text-sm font-medium">Progreso del turno</span>
                <span className="text-white text-sm font-bold">62%</span>
              </div>
              <div className="h-2 w-full bg-white/20 rounded-full overflow-hidden backdrop-blur-sm">
                <div className={`h-full bg-gradient-to-r from-primary to-blue-300 rounded-full`} style={{width: '62%'}}></div>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="px-4 mb-6">
        <h2 className="text-lg font-bold tracking-tight mb-3 px-2">Próximo Turno</h2>
        <div 
          onClick={() => navigate('/month')}
          className="bg-white dark:bg-surface-dark rounded-xl p-4 shadow-sm border border-slate-100 dark:border-slate-800 flex items-center justify-between cursor-pointer active:scale-[0.98] transition-all"
        >
          <div className="flex items-center gap-4">
            <div className={`size-12 rounded-full ${tomorrowDetails.bg} flex items-center justify-center ${tomorrowDetails.color}`}>
              <span className="material-symbols-outlined">{tomorrowDetails.icon}</span>
            </div>
            <div className="flex flex-col">
              <span className="text-xs font-medium text-slate-500 dark:text-slate-400">Mañana, {new Date(now.getTime() + 86400000).toLocaleDateString('es-ES', { day: 'numeric', month: 'short' })}</span>
              <h4 className="text-base font-bold text-slate-900 dark:text-white">Turno {tomorrowDetails.label}</h4>
