                  <span className={`text-[10px] font-semibold ${user.avatarUrl === avatar.url ? 'text-primary' : 'text-slate-500 dark:text-slate-400'}`}>{avatar.label}</span>
                </button>
              ))}
            </div>

            <button 
              onClick={() => setShowAvatarSelector(false)}
              className="w-full py-3 bg-gray-100 dark:bg-gray-800 rounded-xl font-bold text-slate-700 dark:text-white hover:bg-gray-200 transition-colors"
            >
              Cancelar
            </button>
          </div>
        </div>
      )}

      <BottomNav />
    </div>
  );
};

