                <span className="material-symbols-outlined text-slate-400 text-sm group-hover:translate-x-1 transition-transform">chevron_right</span>
              </button>
            ) : (
              <div className="flex flex-col gap-3 animate-fade-up">
                <input type="password" placeholder="Contraseña actual" className="bg-gray-50 dark:bg-[#1a2633] border border-gray-200 dark:border-gray-700 rounded-lg p-3 text-sm outline-none focus:ring-2 focus:ring-primary transition-all" />
                <input type="password" placeholder="Nueva contraseña" className="bg-gray-50 dark:bg-[#1a2633] border border-gray-200 dark:border-gray-700 rounded-lg p-3 text-sm outline-none focus:ring-2 focus:ring-primary transition-all" />
