import React from 'react';
import { useNavigate } from 'react-router-dom';
import { UserConfig, ShiftType, RotationWeek } from '../types';
import { SHIFT_DETAILS } from '../constants';
import BottomNav from '../components/BottomNav';

interface ConfigScreenProps {
  config: UserConfig;
  onUpdate: (config: UserConfig) => void;
}

const ConfigScreen: React.FC<ConfigScreenProps> = ({ config, onUpdate }) => {
  const navigate = useNavigate();

  const addWeek = () => {
    const newWeek: RotationWeek = {
      id: Math.random().toString(36).substr(2, 9),
      shiftType: ShiftType.MORNING
    };
    onUpdate({ ...config, rotation: [...config.rotation, newWeek] });
  };

  const removeWeek = (id: string) => {
    onUpdate({ ...config, rotation: config.rotation.filter(w => w.id !== id) });
  };

  const updateWeekShift = (id: string, shift: ShiftType) => {
    onUpdate({
      ...config,
      rotation: config.rotation.map(w => w.id === id ? { ...w, shiftType: shift } : w)
    });
  };

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onUpdate({ ...config, startDate: e.target.value });
  };

  return (
    <div className="relative flex h-full min-h-screen w-full flex-col overflow-x-hidden pb-32">
      <div className="flex items-center bg-background-light dark:bg-background-dark p-4 pb-2 justify-between sticky top-0 z-50 border-b border-gray-200 dark:border-gray-800 animate-fade-up">
        <button onClick={() => navigate(-1)} className="text-[#111418] dark:text-white flex size-12 shrink-0 items-center justify-center rounded-full hover:bg-gray-100 dark:hover:bg-gray-800 active:scale-90 transition-all">
          <span className="material-symbols-outlined text-[24px]">arrow_back</span>
        </button>
        <h2 className="text-[#111418] dark:text-white text-lg font-bold leading-tight tracking-[-0.015em] flex-1 text-center pr-12">Configuración</h2>
      </div>

      <div className="flex flex-col px-4 pt-6 pb-2 animate-fade-up stagger-1">
        <h1 className="text-[#111418] dark:text-white tracking-light text-[28px] font-bold leading-tight text-left">Define tu Rotación</h1>
        <p className="text-[#637588] dark:text-[#9eaec0] text-base font-normal leading-normal pt-2">
          Elige cuándo inicia tu ciclo y el orden de los turnos.
        </p>
      </div>

      <div className="flex flex-col mt-4 animate-fade-up stagger-2">
        <h3 className="text-[#111418] dark:text-white text-lg font-bold leading-tight tracking-[-0.015em] px-4 pb-3">Fecha de Inicio</h3>
        <div className="px-4">
          <div className="bg-white dark:bg-surface-dark rounded-xl p-4 flex items-center justify-between border border-gray-200 dark:border-gray-800 shadow-sm hover:border-primary/30 transition-all">
            <div className="flex items-center gap-4">
              <div className="bg-primary/10 text-primary flex items-center justify-center size-10 rounded-full animate-pop">
                <span className="material-symbols-outlined text-[22px]">calendar_today</span>
              </div>
              <input 
                type="date" 
                value={config.startDate}
                onChange={handleDateChange}
                className="bg-transparent border-none focus:ring-0 text-[#111418] dark:text-white text-lg font-semibold cursor-pointer"
              />
            </div>
          </div>
        </div>
      </div>

      <div className="flex flex-col mt-8 animate-fade-up stagger-3">
        <div className="flex items-center justify-between px-4 pb-3">
          <h3 className="text-[#111418] dark:text-white text-lg font-bold leading-tight tracking-[-0.015em]">Orden de Turnos</h3>
          <span className="text-xs font-bold text-primary bg-primary/10 px-3 py-1 rounded-full animate-pop">
            {config.rotation.length} Semanas
          </span>
        </div>
        <div className="flex flex-col gap-4 px-4">
          {config.rotation.map((week, index) => (
            <div 
              key={week.id} 
              className={`relative flex flex-col gap-3 bg-white dark:bg-surface-dark rounded-xl p-4 border border-gray-200 dark:border-gray-800 shadow-sm hover:shadow-glow transition-all animate-slide-right stagger-${(index % 4) + 1}`}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <span className="material-symbols-outlined text-[#637588] dark:text-[#506070]">drag_indicator</span>
                  <span className="text-[#111418] dark:text-white text-base font-bold">Semana {index + 1}</span>
                </div>
                <button 
                  onClick={() => removeWeek(week.id)}
                  disabled={config.rotation.length <= 1}
                  className="text-[#637588] dark:text-[#9eaec0] hover:text-red-500 transition-colors disabled:opacity-30 p-2 active:scale-75"
                >
                  <span className="material-symbols-outlined text-[20px]">delete</span>
                </button>
              </div>
              <div className="grid grid-cols-4 gap-2">
                {(Object.keys(SHIFT_DETAILS) as ShiftType[]).map((st) => {
                  const details = SHIFT_DETAILS[st];
                  const isActive = week.shiftType === st;
                  return (
                    <button 
                      key={st}
                      onClick={() => updateWeekShift(week.id, st)}
                      className={`flex flex-col items-center justify-center gap-1 p-2.5 rounded-xl transition-all active:scale-90 ${isActive ? `border-2 ${details.border} ${details.bg} shadow-sm` : 'border border-gray-200 dark:border-gray-700 bg-transparent opacity-60'}`}
                    >
                      <span className={`material-symbols-outlined text-[20px] ${details.color} ${isActive ? 'fill' : ''}`}>{details.icon}</span>
                      <span className={`text-[10px] font-bold uppercase tracking-tighter ${isActive ? details.color : 'text-[#637588] dark:text-[#9eaec0]'}`}>{details.label}</span>
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
          <button onClick={addWeek} className="flex items-center justify-center gap-2 p-4 rounded-xl border-2 border-dashed border-gray-300 dark:border-gray-700 text-[#637588] dark:text-[#9eaec0] hover:border-primary hover:text-primary transition-all group bg-transparent active:scale-[0.98]">
            <span className="material-symbols-outlined group-hover:scale-110 transition-transform">add_circle</span>
            <span className="font-semibold">Agregar semana</span>
          </button>
        </div>
      </div>

      <div className="fixed bottom-0 left-0 w-full bg-white/80 dark:bg-background-dark/95 backdrop-blur-md p-4 border-t border-gray-200 dark:border-gray-800 z-40 animate-fade-up">
        <button onClick={() => navigate('/dashboard')} className="w-full bg-primary hover:bg-blue-600 text-white font-bold text-lg h-14 rounded-xl shadow-lg shadow-primary/25 flex items-center justify-center gap-2 transition-all active:scale-[0.95]">
          <span className="material-symbols-outlined animate-bounce">auto_awesome</span>
          Guardar Configuración
        </button>
      </div>
      <BottomNav />
    </div>
  );
};

export default ConfigScreen;

import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { UserConfig, ShiftType } from '../types';
import { SHIFT_DETAILS } from '../constants';
import BottomNav from '../components/BottomNav';

interface WeeklyScreenProps {
  config: UserConfig;
}

const WeeklyScreen: React.FC<WeeklyScreenProps> = ({ config }) => {
  const navigate = useNavigate();
  const [currentWeekOffset, setCurrentWeekOffset] = useState(0);

  const getShiftForDate = (date: Date) => {
    const start = new Date(config.startDate);
    const startMidnight = new Date(start.getFullYear(), start.getMonth(), start.getDate());
    const dateMidnight = new Date(date.getFullYear(), date.getMonth(), date.getDate());

    const diff = Math.floor((dateMidnight.getTime() - startMidnight.getTime()) / (1000 * 60 * 60 * 24));
    if (diff < 0) return ShiftType.OFF;

    const cycleDays = config.rotation.length * 7;
    const currentDayInCycle = diff % cycleDays;
    const weekIndex = Math.floor(currentDayInCycle / 7);
    return config.rotation[weekIndex].shiftType;
  };

  const weekDays = useMemo(() => {
    const now = new Date();
    const day = now.getDay();
    const diffToMonday = now.getDate() - day + (day === 0 ? -6 : 1);
    const baseMonday = new Date(now.setDate(diffToMonday));
    baseMonday.setHours(0, 0, 0, 0);

    const targetMonday = new Date(baseMonday);
    targetMonday.setDate(baseMonday.getDate() + (currentWeekOffset * 7));

    const days = [];
    for (let i = 0; i < 7; i++) {
      const nextDay = new Date(targetMonday);
      nextDay.setDate(targetMonday.getDate() + i);
      days.push(nextDay);
    }
    return days;
  }, [currentWeekOffset]);

  return (
    <div className="relative flex min-h-screen w-full flex-col max-w-md mx-auto bg-background-light dark:bg-background-dark shadow-2xl overflow-x-hidden">
      <header className="sticky top-0 z-20 flex items-center justify-between bg-surface-light dark:bg-[#111a22]/95 backdrop-blur-md px-4 py-4 border-b border-gray-200 dark:border-[#233648] animate-fade-up">
        <button 
          onClick={() => setCurrentWeekOffset(prev => prev - 1)}
          className="flex items-center justify-center p-2 rounded-full hover:bg-gray-100 dark:hover:bg-[#233648] transition-all active:scale-75 text-slate-600 dark:text-slate-200"
        >
          <span className="material-symbols-outlined text-2xl">chevron_left</span>
        </button>
        <div className="flex flex-col items-center animate-pop">
          <h2 className="text-base font-bold leading-tight tracking-tight">
            {currentWeekOffset === 0 ? 'Esta Semana' : currentWeekOffset === 1 ? 'Próxima Semana' : currentWeekOffset === -1 ? 'Semana Pasada' : `Semana ${currentWeekOffset > 0 ? '+' : ''}${currentWeekOffset}`}
          </h2>
          <span className="text-xs font-medium text-slate-500 dark:text-[#92adc9]">
            {weekDays[0].toLocaleDateString('es-ES', { day: 'numeric', month: 'short' })} - {weekDays[6].toLocaleDateString('es-ES', { day: 'numeric', month: 'short' })}
          </span>
        </div>
        <button 
          onClick={() => setCurrentWeekOffset(prev => prev + 1)}
          className="flex items-center justify-center p-2 rounded-full hover:bg-gray-100 dark:hover:bg-[#233648] transition-all active:scale-75 text-slate-600 dark:text-slate-200"
        >
          <span className="material-symbols-outlined text-2xl">chevron_right</span>
        </button>
      </header>

      <main className="flex-1 flex flex-col gap-4 p-4 pb-24 overflow-y-auto">
        {weekDays.map((day, idx) => {
          const shiftType = getShiftForDate(day);
          const details = SHIFT_DETAILS[shiftType];
          const isToday = day.toDateString() === new Date().toDateString();

          return (
            <details 
              key={idx} 
              className={`group rounded-2xl bg-surface-light dark:bg-surface-dark shadow-sm border ${isToday ? 'border-primary ring-1 ring-primary/20' : 'border-gray-200 dark:border-[#233648]'} overflow-hidden transition-all duration-500 animate-slide-left stagger-${idx + 1}`}
              open={isToday}
            >
              <summary className={`flex cursor-pointer items-center justify-between p-4 bg-transparent hover:bg-gray-50 dark:hover:bg-[#233648]/50 transition-colors select-none ${isToday ? 'bg-primary/5' : ''}`}>
                <div className="flex items-center gap-4">
                  <div className="flex flex-col items-center justify-center w-10">
                    <span className={`text-[10px] font-bold uppercase tracking-widest ${isToday ? 'text-primary' : 'text-slate-500 dark:text-[#92adc9]'}`}>
                      {day.toLocaleDateString('es-ES', { weekday: 'short' })}
                    </span>
                    <span className={`text-xl font-bold ${isToday ? 'text-primary' : 'text-slate-800 dark:text-white'} transition-transform group-hover:scale-110`}>
                      {day.getDate()}
                    </span>
                  </div>
                  <div className="h-8 w-[2px] bg-gray-200 dark:bg-[#233648] rounded-full"></div>
                  <div className="flex flex-col">
                    <div className="flex items-center gap-2">
                      <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-wider ${details.bg} ${details.color} border ${details.border}/20`}>
                        {details.label}
                      </span>
                      <span className="text-[11px] font-semibold text-slate-400">{details.time}</span>
                    </div>
                    {shiftType !== ShiftType.OFF ? (
                      <p className="text-sm font-bold text-slate-700 dark:text-slate-200 mt-1">Turno programado</p>
                    ) : (
                      <p className="text-sm font-medium text-slate-400 dark:text-slate-500 mt-1 italic">Día libre</p>
                    )}
                  </div>
                </div>
                <span className={`material-symbols-outlined transition-transform duration-500 group-open:rotate-180 ${isToday ? 'text-primary' : 'text-slate-400'}`}>expand_more</span>
              </summary>
              <div className="px-4 pb-4 pt-1 border-t border-gray-100 dark:border-[#233648]/50 animate-fade-up">
                <div className="flex flex-col gap-3 mt-2">
                  <div className="flex items-start gap-3">
                    <span className="material-symbols-outlined text-slate-400 text-lg mt-0.5">sticky_note_2</span>
                    <div className="flex flex-col">
                      <p className="text-sm text-slate-600 dark:text-[#92adc9] leading-relaxed">
                        {shiftType === ShiftType.OFF ? "Día de recuperación. Aprovecha para descansar al máximo." : `Preparado para el turno de ${details.label.toLowerCase()}. Revisa tu equipo.`}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </details>
          );
        })}
      </main>

      <div className="fixed bottom-24 right-5 z-20 animate-pop stagger-5">
        <button 
          onClick={() => navigate('/config')}
          className="flex h-14 w-14 items-center justify-center rounded-full bg-primary shadow-xl shadow-blue-500/40 text-white hover:bg-blue-600 hover:rotate-90 active:scale-90 transition-all"
        >
          <span className="material-symbols-outlined text-3xl font-light">edit_calendar</span>
        </button>
      </div>

      <BottomNav />
    </div>
  );
};

export default WeeklyScreen;
